/// <summary>
/// CB624_TMSEngineSOCreation
/// Class to proceede with the creation/cancellation process for TMS engine
/// </summary>
abstract class METTMSEngineTransferOrderProccess
{
    TMSCarrierCode              carrierCode;
    InventTransferTable         transferTable;
    boolean                     isOrderPerishable;
    boolean                     isToteCustomer;
    METInventTransferTableExt   metTransferTable;
    TransDate                   shippingDate;
    METTMSShipmentID            shipmentId;
    InventLocation              inventLocation;
    METInventLocation           metInventLocationFrom;
    METInventLocation           metInventLocationTo;
    boolean                     shipmentCreated;
    TransDate                   deliveryDate;
    boolean                     hasCCR;

    METTMSShipmentItemGroupTOHelper             TSIGHelper;
    METTMSEngineTransferOrderProccessLinesTmp   proccessLinesTmp;

}

