/// <summary>
/// Public construct method to TMS Engine Transfer order process
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineTransferOrderProccess enum</param>
/// <param name = "_sourceRecord">Source record parameter for TMS engine</param>
/// <param name = "_postingIdentifier">Posting identifier e.g. delivery note number</param>
/// <returns>Instance of <c>METTMSEngineTransferOrderProccess</c></returns>
public static METTMSEngineTransferOrderProccess construct(METTMSEngineTransferOrderProcess _tmsEngineProcess, Common _sourceRecord, str _postingIdentifier = '')
{
    METTMSEngineTransferOrderProccess process;
    boolean error = false;
    //str postingIdentifier = _postingIdentifier;

    switch (_tmsEngineProcess)
    {
        //case (METTMSEngineTransferOrderProcess::Cancellation) :
        //    if (_sourceRecord is InventTransferTable)
        //    {
        //        //process = new METTMSEngineSalesOrderProccess_Cancellation(_sourceRecord);
        //    }
        //    else
        //    {
        //        error = true;
        //    }
        //    break;

        case (METTMSEngineTransferOrderProcess::Creation) :
            if (_sourceRecord is InventTransferTable)
            {
                process = new METTMSEngineTransferOrderProccess_Creation(_sourceRecord);
            }
            else
            {
                error = true;
            }
            break;

        default:
            error = true;
            break;
    }

    if (error)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }

    return process;
}

/// <summary>
/// main method
/// </summary>
/// <param name = "_args">args</param>
public static void main(Args _args)
{
    METTMSEngineTransferOrderProcess    tmsEngineTransferOrderProcess;
    InventTransferTable                 transferTableLoc;
    Common common;

    if (_args.record())
    {
        tmsEngineTransferOrderProcess = _args.parmEnum();
        common = _args.record();
        METTMSEngineTransferOrderProccess process = METTMSEngineTransferOrderProccess::construct(tmsEngineTransferOrderProcess, common);

        process.run();

        if (common is InventTransferTable)
        {
            transferTableLoc = common as InventTransferTable;
        }

        if (process.isShipmentCreated())
        {
            info(strFmt("@MET:TMSEngineSuccessMsgTO", transferTableLoc.TransferId));
        }
        else
        {
            info(strFmt("@MET:TMSEngineCompletedMsgTO", transferTableLoc.TransferId));
        }
    }
    else
    {
        throw error(strfmt("@SYS29104", funcname())); // Class %1 must be called with a buffer.
    }
}

/// <summary>
/// initialize default parameters and variables
/// </summary>
/// <param name = "_transferTable">InventTransferTable record</param>
protected void init(InventTransferTable    _transferTable)
{
    transferTable           = _transferTable;
    metTransferTable        = transferTable.metInventTransferTableExt();
    carrierCode             = TMSInventTransferTable::find(transferTable.TransferId).CarrierCode;
    isOrderPerishable       = METTMSEngineTransferOrderProccess::IsOrderPerishable(metTransferTable);
    metInventLocationFrom   = METInventLocation::findByInventLocationId(transferTable.InventLocationIdFrom);
    metInventLocationTo     = METInventLocation::findByInventLocationId(transferTable.InventLocationIdTo);

    isToteCustomer          = CustTable::METIsToteCustomer(metInventLocationTo.InternalCustomer, metInventLocationTo.DataAreaId);

    // initialise shipping and delivery date variables
    shippingDate = this.shippingDate();
    deliveryDate = this.deliveryDate();        
}

/// <summary>
/// Validate TMS engine in On on the warehouse
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean useTMSEngine()
{
    return metInventLocationFrom.IsTMSEngineUsed;
}

/// <summary>
/// Validate if Perishable SOs are excluded from TMS
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
boolean excludePerishable()
{
    return metInventLocationFrom.ExcludePerishables;
}

/// <summary>
/// Refactored new validate method
/// </summary>
/// <returns>true if valdidation successful; otherwise, false.</returns>
protected boolean validate()
{
    //Step 1: check if order should be excluded from TMS Engine processing
    if (//!salesTable.METIsSalesOrderExcluded() &&
        carrierCode &&
        metTransferTable.Route &&
        this.useTMSEngine() &&
        (!isOrderPerishable ||
        (isOrderPerishable  && !this.excludePerishable())))
    {
        return true;
    }

    return false;
}

/// <summary>
/// New method to retrieve the METTMSShipmentOrderTable
/// For creation, straight forward with Transfer order number
/// Overridden in child classes for packing slip
/// </summary>
/// <param name = "_transferId">Transfer order number</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(InventTransferId _transferId, WMSPickingRouteID _pickingRouteId = '')
{
    return METTMSShipmentOrderTable::findByOrder(_transferId, _pickingRouteId);
}

/// <summary>
/// Run the TMS engine
/// </summary>
public void run()
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentTable         tmsShipmentTableCancel;
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    //Step 1: check if order should be excluded from TMS Engine processing
    if (this.validate())
    {
        this.initTmpTable();

        try
        {
            ttsbegin;

            tmsShipmentOrderTable   = this.getTMSShipmentOrderTable(transferTable.TransferId);
            //Step 2: Check if the order is already on a shipment
            if (!tmsShipmentOrderTable.RecId)
            {
                //Step 3: If order is not on any existing shipment
                tmsShipmentTable = this.initTMSShipment();

                //Step 3a: check if there is an existing shipment this order can be made part of.
                if (!tmsShipmentTable.RecId)
                {
                    this.createShipment();
                }
                else
                {
                    //Step 3c: If a shipment exists, update it
                    this.createShipment(false);
                }
            }
            else
            {
                tmsShipmentTable = this.initTMSShipment();
                //Step 4: If order is on an existing shipment and there is a change to either Route or Ship date
                if (tmsShipmentOrderTable.ShipmentId != shipmentId)
                {
                    //Step 4a: Get the “TMS Shipment” record related to the “TMS Shipment Order”
                    tmsShipmentTableCancel = METTMSShipmentTable::find(tmsShipmentOrderTable.ShipmentId);

                    //Step 4c: Update the current “TMS Shipment” - cancel it
                    this.cancelShipment(transferTable.TransferId);

                    //Step 4d: Link the Transfer order to a new or existing shipment
                    this.createShipment(!tmsShipmentTable);

                }
                else
                {
                    //Step 5: If order is on an existing shipment and there is no change to both Route and Ship date
                    //delete Shipment itemgroup - recreate                        
                    delete_from tmsShipmentOrderTable
                        where tmsShipmentOrderTable.ShipmentId  == shipmentId
                        // CB626_TMSEngineSOPackingSlip There could be multiple orders in the same shipment
                            && tmsShipmentOrderTable.OrderNumber == transferTable.TransferId;
                    //Step 3d: Create TMS Shipment Order record
                    //Step 4d: Link the transfer order to a new shipment
                    this.createShipment(false);
                }
            }

            //Step 6: Update order and shipment totals
            //Step 6a: Update the order’s “Order weight”
            //Step 6b: Update the order’s “Order volume”
            //Step 6c: Update order’s “Pallet Total footprint”
            this.updateTMSShipmentOrder();

            //Step 6d: Update the shipment’s “Pallet lifts”
            this.updateTMSShipment(shipmentId);

            ttscommit;
        }
        catch (Exception::Error)
        {
            //An error occurs during the creation or updates of the staging records
            error(this.errorMessage());
        }
    }
}

/// <summary>
/// Create an instance of <c>METTMSEngineTOLinesTmpBuilder</c>
/// </summary>
/// <param name = "_tmsEngineProcess">METTMSEngineTransferOrderProcess enum</param>
/// <param name = "_transferTable"><c>InventTransferTable</c> record</param>
/// <returns>New instance of <c>METTMSEngineTOLinesTmpBuilder</c></returns>
METTMSEngineTOLinesTmpBuilder getTmpBuilderInstance(METTMSEngineTransferOrderProcess _tmsEngineProcess, InventTransferTable _transferTable)
{
    return METTMSEngineTOLinesTmpBuilder::construct(_tmsEngineProcess, _transferTable);
}

/// <summary>
/// Initialise temporary table with calculations
/// </summary>
void initTmpTable()
{        
    METTMSEngineTOLinesTmpBuilder tmpBuilder = this.getTmpBuilderInstance(METTMSEngineTransferOrderProcess::Creation, transferTable);
    proccessLinesTmp = tmpBuilder.populateTmpTable();
    hasCCR = tmpBuilder.hasCCR();
}

/// <summary>
/// cancel TMS shipment
/// </summary>
/// <param name = "_transferId">InventTransferId</param>
void cancelShipment(InventTransferId _transferId)
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentOrderTable    tMSShipmentOrderTable;
    METTMSShipmentOrderTable    tMSShipmentOrderTableExist;

    ttsbegin;
    select firstonly forupdate tMSShipmentOrderTable
                where tMSShipmentOrderTable.OrderNumber == _transferId;
    if (tMSShipmentOrderTable.RecId)
    {
        tMSShipmentTable = METTMSShipmentTable::find(tMSShipmentOrderTable.ShipmentId, true);
        tMSShipmentOrderTable.delete();

        tMSShipmentTable.TMSSendStatus = METTMSSendStatus::ToBeSent;

        select firstonly RecId from tMSShipmentOrderTableExist
                    where tMSShipmentOrderTableExist.ShipmentId == tMSShipmentTable.ShipmentID
                    && tMSShipmentOrderTableExist.RecId != tMSShipmentOrderTable.RecId;
        if (!tMSShipmentOrderTableExist.RecId)
        {                        
            tMSShipmentTable.ShipmentStatus = METCashShipmentStatus::Cancelled;
        }
        tMSShipmentTable.update();

        // to update the PalletLifts after removing the TSO, excluding delivery note number
        this.updateTMSShipment(tMSShipmentTable.shipmentId, false);
    }
    ttscommit;
}

/// <summary>
/// Return if shipment created/updated
/// </summary>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
private boolean isShipmentCreated()
{
    return shipmentCreated;
}

/// <summary>
/// create tms shipment tables
/// </summary>
/// <param name = "_isCreateTMSShipment">boolean</param>
protected void createShipment(boolean     _isCreateTMSShipment = true)
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    //Step 3b: If no shipment exists, create a new one
    if (_isCreateTMSShipment)
    {
        this.createTMSShipment();
    }
    //Step 3d: Create TMS Shipment Order record
    tmsShipmentOrderTable = this.createTMSShipmentOrder();

    //Step 3e: Create TMS Shipment Item Group records
    // CB626_TMSEngineSOPackingSlip refactoring TSIG record creation
    //this.createTMSShipmentItemGroup(tmsShipmentOrderTable.TMSShipmentOrderIdentifier);
    shipmentCreated = this.createTMSShipmentItemGroup(proccessLinesTmp, tmsShipmentOrderTable.TMSShipmentOrderIdentifier, isToteCustomer, transferTable.InventLocationIdFrom, hasCCR);
}

/// <summary>
/// Create an instance of <c>METTMSShipmentItemGroupHelper</c>
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>New instance of <c>METTMSShipmentItemGroupHelper</c></returns>
METTMSShipmentItemGroupTOHelper getTSIGHelperInstance(METTMSEngineTransferOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    return METTMSShipmentItemGroupTOHelper::construct(_processLinesTmp,
                                                    _tmsShipmentOrderIdentifier,
                                                    _isToteCustomer,
                                                    _headerInventLocationId,
                                                    _hasCCR);
}

/// <summary>
/// Create TSIG record
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>True if creation successful; otherwise, false.</returns>
protected boolean createTMSShipmentItemGroup(METTMSEngineTransferOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    boolean ret;
    TSIGHelper = this.getTSIGHelperInstance(_processLinesTmp, _tmsShipmentOrderIdentifier, _isToteCustomer, _headerInventLocationId, _hasCCR);
    ret = TSIGHelper.create();
    return ret;
}

/// <summary>
/// Step 3a: check if there is an existing shipment this order can be made part of.
/// </summary>
/// <returns>Instance of <c>METTMSShipmentTable</c></returns>
protected METTMSShipmentTable initTMSShipment()
{
    str     shippingDateStr;

    shippingDateStr = date2Str
        (shippingDate,
            321,
            DateDay::Digits2,
            DateSeparator::None,
            DateMonth::Digits2,
            DateSeparator::None,
            DateYear::Digits4);

    shipmentId  = strFmt("@MET:ShipmentStrFmt", transferTable.InventLocationIdFrom, transferTable.InventLocationIdTo, metTransferTable.Route, shippingDateStr);

    return METTMSShipmentTable::find(shipmentId);
}

/// <summary>
/// Step 3b: If no shipment exists, create a new one
/// </summary>
protected void createTMSShipment()
{
    METTMSShipmentTable tmsShipmentTable;

    this.setTMSShipmentFields(tmsShipmentTable);
    tmsShipmentTable.insert();
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentTable</c> record
/// </summary>
/// <param name = "_tmsShipmentTable"><c>METTMSShipmentTable</c> record</param>
protected void setTMSShipmentFields(METTMSShipmentTable _tmsShipmentTable)
{
    METRouteStopTable   routeStopTable = METRouteStopTable::findByRouteIdentifier(metTransferTable.RouteStopIdentifier);
    METRouteTable       routeTable = METRouteTable::findByRouteIdentifier(metTransferTable.RouteStopIdentifier);

    _tmsShipmentTable.ShipmentID                    = shipmentId;
    _tmsShipmentTable.SourceWarehouse               = transferTable.InventLocationIdFrom;
    _tmsShipmentTable.DestinationType               = METDestinationType::Warehouse;
    _tmsShipmentTable.DestinationCustomer           = '';
    _tmsShipmentTable.DestinationWarehouse          = transferTable.InventLocationIdTo;
    _tmsShipmentTable.Route                         = metTransferTable.Route;
    _tmsShipmentTable.ConfirmedShipDate             = shippingDate;
    _tmsShipmentTable.TMSSendStatus                 = METTMSSendStatus::ToBeSent;
    _tmsShipmentTable.ShipmentStatus                = METCashShipmentStatus::Active;
    _tmsShipmentTable.RouteStop                     = int2str(metTransferTable.RouteStopNum);
    _tmsShipmentTable.WarehouseZone                 = routeStopTable.Zone ? routeStopTable.Zone : routeTable.Zone;
    _tmsShipmentTable.StagingLane                   = metTransferTable.StagingLane;
    _tmsShipmentTable.PickupEarliest                = this.formatUSDate(shippingDate, routeTable.ReadyTime);
    _tmsShipmentTable.PickupLatest                  = this.formatUSDate(shippingDate, routeTable.DispatchTime);
    _tmsShipmentTable.DeliveryEarliest              = this.formatUSDate(deliveryDate, routeStopTable.TimeWindowStart);
    _tmsShipmentTable.DeliveryLatest                = this.formatUSDate(deliveryDate, routeStopTable.TimeWindowEnd);
    _tmsShipmentTable.Carrier                       = carrierCode;
    _tmsShipmentTable.SpecialDeliveryInstructions   = this.getCustomerInstruction();
    _tmsShipmentTable.FinalisationtId               = '';
    _tmsShipmentTable.ChepPalletCount               = 0;
    _tmsShipmentTable.LoscamPalletCount             = 0;
    _tmsShipmentTable.PlainPalletCount              = 0;
}

/// <summary>
/// init Customer instruction
/// </summary>
/// <returns>value for <c>METCustomerInstruction</c></returns>
private METCustomerInstruction getCustomerInstruction()
{
    METWarehouseCarrierCustomerView warehouseCarrierCustomerView;
    TransDate                       today               = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

    select firstonly CustomerInstruction from warehouseCarrierCustomerView
        where warehouseCarrierCustomerView.CustAccount == metInventLocationTo.InternalCustomer
            && warehouseCarrierCustomerView.StartDate <= today
            && warehouseCarrierCustomerView.EndDate >= today;

    return warehouseCarrierCustomerView.CustomerInstruction;
}

/// <summary>
/// Step 3c: If a shipment exists, update it
/// </summary>
/// <param name = "_shipmentId">TMS shipment Id</param>
/// <param name = "_updateFinalisationId">Update finalisation id</param>
/// <param name = "_updateActuals">Update actual pallet counts</param>
void updateTMSShipment(METTMSShipmentID _shipmentId, boolean _updateFinalisationId = true, boolean _updateActuals = false)
{
    METTMSShipmentTable         tmsShipmentTable;
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    // calc sum PalletTotalFootprint for the shipment
    select sum(PalletTotalFootprint) from tmsShipmentOrderTable
            where tmsShipmentOrderTable.ShipmentId == _shipmentId;

    // Create SysDaUpdateObject object
    var uo = new SysDaUpdateObject(tmsShipmentTable);

    // Update setting clause
    this.updateTMSShipmentSettingClause(uo, tmsShipmentOrderTable.PalletTotalFootprint, _updateFinalisationId, _updateActuals);

    // Add where clause
    uo.whereClause(new SysDaEqualsExpression(
                   new SysDaFieldExpression(tmsShipmentTable, fieldStr(METTMSShipmentTable, ShipmentID)),
                   new SysDaValueExpression(_shipmentId)));

    // execute update_recordset
    new SysDaUpdateStatement().update(uo);
}

/// <summary>
/// Update TS setting clause
/// </summary>
/// <param name = "_uo"><c>SysDaUpdateObject</c> instance</param>
/// <param name = "_palletTotalFootprint">Pallet total footprint</param>
/// <param name = "_updateFinalisationId">Update finalisation id</param>
/// <param name = "_updateActuals">Update actual pallet counts</param>
void updateTMSShipmentSettingClause(SysDaUpdateObject _uo, METQty _palletTotalFootprint, boolean _updateFinalisationId, boolean _updateActuals)
{
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, TMSSendStatus), new SysDaValueExpression(METTMSSendStatus::ToBeSent));
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, ShipmentStatus), new SysDaValueExpression(METCashShipmentStatus::Active));
    _uo.settingClause().add(fieldStr(METTMSShipmentTable, PalletLifts), new SysDaValueExpression(_palletTotalFootprint));
}

/// <summary>
/// Step 3d: Create TMS Shipment Order record
/// </summary>
/// <returns>Instance of <c>METTMSShipmentOrderTable</c></returns>
METTMSShipmentOrderTable createTMSShipmentOrder()
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;

    this.setTMSShipmentOrderFields(tmsShipmentOrderTable);
    tmsShipmentOrderTable.insert();

    return tmsShipmentOrderTable;
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    _tmsShipmentOrderTable.initValue();
    _tmsShipmentOrderTable.ShipmentId       = shipmentId;
    _tmsShipmentOrderTable.OrderNumber      = transferTable.TransferId;
    _tmsShipmentOrderTable.IsCrossDockOrder = metTransferTable.TransferType == METCrossDockTransferType::CrossDock ? NoYes::Yes : NoYes::No;

    METTMSEngineTransferOrderProccessLinesTmp  linesTmp;
    linesTmp.linkPhysicalTableInstance(proccessLinesTmp);

    // BrokenCaseItemQtySecurity and BrokenCaseItemQtyNonSecurity are sum from temp table
    select sum(BrokenCasesCountNonSecurity), sum(BrokenCasesCountSecurity), sum(RepackCountNonSecurity), sum(RepackCountSecurity), sum(CaseQty_CaseLines) from linesTmp;

    _tmsShipmentOrderTable.BrokenCaseItemQtySecurity    = linesTmp.BrokenCasesCountSecurity;
    _tmsShipmentOrderTable.BrokenCaseItemQtyNonSecurity = linesTmp.BrokenCasesCountNonSecurity;
    _tmsShipmentOrderTable.RepackCaseCountSecurity      = linesTmp.RepackCountSecurity;
    _tmsShipmentOrderTable.RepackCaseCountNonSecurity   = linesTmp.RepackCountNonSecurity;

    _tmsShipmentOrderTable.CaseCountShipped             = linesTmp.CaseQty_CaseLines + this.getRepackContainersByCommodity(linesTmp.RepackCountSecurity, linesTmp.RepackCountNonSecurity);
    _tmsShipmentOrderTable.CaseCountSecurity            = _tmsShipmentOrderTable.RepackCaseCountSecurity;
    _tmsShipmentOrderTable.SSCC                         = '';
    _tmsShipmentOrderTable.XDockWMSUpdateReceived       = NoYes::No; // TODO
    _tmsShipmentOrderTable.VendorNumber                 = '';
}

/// <summary>
/// RepackContainersByCommodity = sum of (roundUp(RepackCountSecurity) + roundUp(RepackCountNonSecurity)) for all the lines on the order per LineCommodity
/// </summary>
/// <param name = "_repackCountSecurity">Repack count security</param>
/// <param name = "_repackCountNonSecurity">Repack count non security</param>
/// <returns>int <c>Int</c></returns>
protected int getRepackContainersByCommodity(real _repackCountSecurity, real _repackCountNonSecurity)
{
    return roundUp(_repackCountSecurity, 1) + roundUp(_repackCountNonSecurity, 1);
}

/// <summary>
/// Step 6a: Update the order’s “Order weight”
/// Step 6b: Update the order’s “Order volume”
/// Step 6c: Update order’s “Pallet Total footprint”
/// </summary>
void updateTMSShipmentOrder()
{
    METTMSShipmentOrderTable    tmsShipmentOrderTable;
    METTMSShipmentItemGroup     tmsShipmentItemGroup;

    update_recordset tmsShipmentOrderTable
        setting OrderWeight = tmsShipmentItemGroup.Weight,
                OrderVolume = tmsShipmentItemGroup.Cube
        join sum(Weight), sum(Cube) from tmsShipmentItemGroup
            where tmsShipmentOrderTable.ShipmentId == shipmentId
                && tmsShipmentOrderTable.OrderNumber == transferTable.TransferId
                && tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                && (tmsShipmentItemGroup.QuantityUOM == METConstants::unitCSE
                || tmsShipmentItemGroup.QuantityUOM like METConstants::KegQtyUOM
                || tmsShipmentItemGroup.QuantityUOM == METConstants::unitTOT);

    update_recordset tmsShipmentOrderTable
        setting PalletTotalFootprint = tmsShipmentItemGroup.Quantity
        join sum(Quantity) from tmsShipmentItemGroup
            where tmsShipmentOrderTable.ShipmentId == shipmentId
                && tmsShipmentOrderTable.OrderNumber == transferTable.TransferId
                && tmsShipmentItemGroup.TMSShipmentOrderIdentifier == tmsShipmentOrderTable.TMSShipmentOrderIdentifier
                && tmsShipmentItemGroup.QuantityUOM == METConstants::unitPal;
}

/// <summary>
/// Shipping date variable
/// </summary>
/// <returns>Shipping date</returns>
TransDate shippingDate()
{
    return transferTable.ShipDate;
}

/// <summary>
/// Delivery date variable
/// </summary>
/// <returns>Delivery date</returns>
TransDate deliveryDate()
{
    return transferTable.ReceiveDate;
}

/// <summary>
/// TMS needs US date format, concatenate date and time(str)
/// </summary>
/// <param name = "_date">TMS delivery or shipping date</param>
/// <param name = "_time">Route or route stop time format HHmm</param>
/// <returns>Formatted date and time in US format mm/dd/yyyy hh:mm</returns>
METDelivery formatUSDate(TransDate _date, METRouteTime _time)
{
    return strFmt(METConstants::value1SpaceValue2, date2Str(_date, 213, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4), strIns(_time, METConstants::colon, 3));
}

/// <summary>
/// Error message
/// </summary>
/// <returns>error txt</returns>
abstract protected ErrorTxt errorMessage()
{

}

/// <summary>
/// Validate if order is Perishable
/// </summary>
/// <param name = "_metTransferTable">METInventTransferTableExt</param>
/// <returns>
/// a boolean value<c>boolean</c> query.
/// </returns>
public static boolean IsOrderPerishable(METInventTransferTableExt _metTransferTable)
{
    InventParameters    inventParameters = InventParameters::find();
    boolean             ret = false;
    if (inventParameters.METPerishableOrderSplitGroup)
    {
        ret = _metTransferTable.OrderSplitGroup == inventParameters.METPerishableOrderSplitGroup;
    }
    return ret;
}
